def agent_action(sandbox, agent_body, step_count):
    # Ensure required attributes are initialized
    if not hasattr(agent_body, 'wind_period'):
        agent_body.wind_period = None
        agent_body.wind_strength = 0.0
        agent_body.peak_times = []
        agent_body.last_vx = 0.0
        agent_body.velocity_history = []

    # Get seat state
    seat = sandbox.get_swing_seat()
    pos = seat.position
    vel = seat.linearVelocity
    current_time = sandbox.get_sim_time()
    vx = vel.x
    vy = vel.y

    # Update velocity history for wind estimation
    agent_body.velocity_history.append(vx)
    if len(agent_body.velocity_history) > 10:
        agent_body.velocity_history.pop(0)

    # Track horizontal velocity peaks to estimate wind period
    if len(agent_body.peak_times) < 10:
        if vx > agent_body.last_vx:
            agent_body.peak_times.append(current_time)
        agent_body.last_vx = vx
    else:
        if len(agent_body.peak_times) >= 2:
            last_peak = agent_body.peak_times[-1]
            prev_peak = agent_body.peak_times[-2]
            period_candidate = current_time - last_peak
            if agent_body.wind_period is None:
                agent_body.wind_period = period_candidate
            else:
                agent_body.wind_period = (
                    agent_body.wind_period * (len(agent_body.peak_times) - 1) + period_candidate
                ) / len(agent_body.peak_times)

    # Estimate wind strength from max velocity
    if agent_body.peak_times:
        max_vx = max(agent_body.velocity_history)
        agent_body.wind_strength = max_vx * 1.2  # Safety factor

    # Apply horizontal force to counteract wind and move towards target x range
    fx = 0.0
    if agent_body.wind_period is not None and vx != 0:
        phase = (current_time % agent_body.wind_period) / agent_body.wind_period
        wind_force = agent_body.wind_strength * math.sin(2 * math.pi * phase)
        fx = -wind_force
        fx = max(-42.0, min(fx, 42.0))
    else:
        # If wind not yet estimated, apply force towards target x range
        if pos.x < 9.35:
            fx = 42.0
        elif pos.x > 10.65:
            fx = -42.0
        else:
            fx = 0.0

    # Apply vertical force to reach target zone
    fy = 0.0
